head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnVisible]<br/>Body Column 정보를 사용하여 특정 Column 의 숨김(Visible) 여부를 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 숨김 여부를 조회할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "반환값이 true 이면 해당 Column 이 표시된 상태입니다.",
        "반환값이 false 이면 해당 Column 이 숨겨진 상태입니다.",
        "파라미터에 유효하지 않은 값을 설정하면 undefined 를 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 인덱스 - 0:name(text) / 1:memo(text, 숨김 setColumnVisible(1,false)) / 2:qty(number) / 3:total(number). 숨김 컬럼도 포함하여 인덱스가 부여됨. 데이터 Row 4개.\n[절차] columnInfo(인덱스) 선택 후 (getColumnVisible 실행) 클릭.\n[확인] 표시 Column(0/2/3)=true / 숨김 Column(1)=false / 유효하지 않은 값(99)=undefined 가 반환영역에 출력됨."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="number"></w2:column>';
    strDlt += '<w2:column id="total" name="total" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "노트북", "memo": "재고확인", "qty": 3, "total": 3000 },
        { "name": "모니터", "memo": "신규입고", "qty": 5, "total": 5000 },
        { "name": "키보드", "memo": "할인적용", "qty": 7, "total": 7000 },
        { "name": "마우스", "memo": "주문대기", "qty": 9, "total": 9000 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 + gBody)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:560px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnVisible 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol1" value="품목"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="메모(숨김)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="수량"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : name (text)
    strTarget += '<w2:column width="140" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 1 : memo (text) - setColumnVisible(1,false) 로 숨김 -> 숨김 포함 인덱스 검증용
    strTarget += '<w2:column width="120" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    // index 2 : qty (number)
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="number" id="qty" dataList="qty"></w2:column>';
    // index 3 : total (number)
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" id="total" dataList="total"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(memo, 인덱스 1) 숨김 -> 숨김 Column 포함 인덱스 + false 케이스 검증용
    target1.setColumnVisible(1, false);
}



// getColumnVisible 조회 (메인 검증)
scwin.btn_getColumnVisible_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    // getColumnVisible : 해당 Column 의 숨김 여부 반환 (표시=true / 숨김=false / 유효하지 않은 값=undefined)
    let isVisible = target1.getColumnVisible(columnInfo);

    // undefined 도 구분하여 출력
    let stateLabel;
    if (typeof isVisible === 'undefined') {
        stateLabel = "undefined (유효하지않음)";
    } else {
        stateLabel = isVisible + " (" + (isVisible ? "표시" : "숨김") + ")";
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnVisible(" + columnInfo + ") -> 반환값: " + stateLabel);
}
